changeSet.sql:
UPDATE workspace SET per_person_results_for_admins = true WHERE EXISTS (SELECT 1 FROM review r WHERE r.workspace_id = workspace.id);
INSERT INTO config_audit_event (workspace_id, actor_kind, entity_type, entity_id, action, changed_keys, old_value, new_value)
SELECT id, 'SYSTEM', 'WORKSPACE_VISIBILITY', id::text, 'CREATED', ARRAY['perPersonResultsForAdmins', 'keptFromBefore'], NULL,
       '{"perPersonResultsForAdmins":true,"keptFromBefore":true}'
FROM workspace WHERE per_person_results_for_admins = true;
